def compute(vars):
    crude_oil_barrels = vars["v1"]
    total_pipeline_barrels = vars["v2"]

    if total_pipeline_barrels == 0:
        return None

    ratio = crude_oil_barrels / total_pipeline_barrels
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "crude_oil_barrels": crude_oil_barrels,
            "total_pipeline_barrels": total_pipeline_barrels,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
